<?php require_once __DIR__ . '/../../includes/layout.php'; require_role(['Admin']); render_header('Activity Logs'); ?><div class="page-title"><div><h1>Activity Logs</h1><p>Audit trail and system activities.</p></div></div><div class="panel"><div class="table-responsive"><table class="table"><thead><tr><th>Date</th><th>User</th><th>Action</th><th>Details</th></tr></thead><tbody><?php foreach(rows('SELECT l.*,u.full_name FROM activity_logs l LEFT JOIN users u ON u.id=l.user_id ORDER BY l.created_at DESC LIMIT 300') as $l): ?><tr><td><?= e($l['created_at']) ?></td><td><?= e($l['full_name'] ?? 'System') ?></td><td><?= e($l['action']) ?></td><td><?= e($l['details']) ?></td></tr><?php endforeach; ?></tbody></table></div></div><?php render_footer(); ?>
